mapper.select:
        select FINPROD_MARKET_ID id, IFNULL(FINPROD_ABBR, FINPROD_NAME) text, FINPROD_ID object from FIN_PRODUCT


                and (instr(FINPROD_MARKET_ID, #{search}) > 0
                or instr(FINPROD_ID, #{search}) > 0
                or instr(FINPROD_NAME, #{search}) > 0
                or instr(FINPROD_ABBR, #{search}) > 0)


                and FINPROD_TYPE2 = #{finprodType2}


                and PROFIT_TYPE = #{profitType}


				AND FINPROD_MARKET_ID = #{initValue}

select.if:
UNION ALL
SELECT '${TRADE_FLOW_STATUS03}' statusValid, T1.TOTLE_TRADE_ID busiCode, T5.FINPROD_ID, T5.FINPROD_MARKET_ID, T5.FINPROD_ABBR, T1.CHL_ID, T4.FINPROD_NAME, T1.PS, T3.REG_DATE, T2.TRADE_DATE, T2.SETTLE_DATE, T2.UNIT_CPRICE, T2.UNIT_INT, sum(T3.REG_DATE_AMT) REG_DATE_AMT, sum(T2.FPRICE_AMT) FPRICE_AMT, sum(T2.SHARE_AMT) SHARE_AMT FROM TRD_FIN_PRODUCT_DEAL_TOTAL T1 LEFT JOIN TRD_PRODUCT_DEAL T2 ON T1.TOTLE_TRADE_ID = T2.TOTLE_TRADE_ID AND T2.PS = #{PS_T13,jdbcType=VARCHAR} LEFT JOIN TRD_PRODUCT_DEAL_ADD T3 ON T2.TRADE_ID = T3.TRADE_ID LEFT JOIN FIN_PRODUCT T4 ON T1.CHL_ID = T4.FINPROD_ID AND T4.IS_CHL = #{YES_OR_NO_Y,jdbcType=VARCHAR} LEFT JOIN FIN_PRODUCT T5 ON T1.FINPROD_ID = T5.FINPROD_ID left join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = T3.PORTFOLIO_ID WHERE T1.P_TRADE_ID IS NULL AND T1.IS_CANCEL = #{YES_OR_NO_Y} AND T1.FINPROD_TYPE2 = #{F10} and IFNULL(pp.PARENT_PORTFOLIO_ID,'null') = 'null'
AND T1.TOTLE_TRADE_ID = #{busiCode}
AND (T1.SEC_MANAGE_ACCT_ID IN (
null) OR T1.SEC_MANAGE_ACCT_ID IN (
#{item}
))
AND (T5.FINPROD_MARKET_ID IN
null) or T5.FINPROD_MARKET_ID in (
#{item}
)
AND (T1.CHL_ID IN
null) or T1.CHL_ID in (
#{item}
)
AND T1.PS IN (#{item})
AND T3.REG_DATE >= STR_TO_DATE(#{registDateStart},'%Y-%m-%d')
AND T3.REG_DATE <= STR_TO_DATE(#{registDateEnd},'%Y-%m-%d')
AND T2.TRADE_DATE >= STR_TO_DATE(#{exRightsDateStart},'%Y-%m-%d')
AND T2.TRADE_DATE <= STR_TO_DATE(#{exRightsDateEnd},'%Y-%m-%d')
GROUP BY T1.IS_CANCEL, T1.TOTLE_TRADE_ID, T5.FINPROD_ID, T5.FINPROD_MARKET_ID, T5.FINPROD_ABBR, T1.CHL_ID, T4.FINPROD_NAME, T1.PS, T3.REG_DATE, T2.TRADE_DATE, T2.SETTLE_DATE, T2.UNIT_CPRICE, T2.UNIT_INT

mapper.select:
SELECT psp.PORTFOLIO_ID portfolioId, pp.PORTFOLIO_NAME portfolioName, psp.SEC_ACCT_ID secAcctId, psp.AMOUNT regDateAmt, psp.CDATE regDate,
pp.INVEST_YESORNO investYesorno
from PTL_SEC_POSITION psp inner join FIN_PRODUCT fp on fp.FINPROD_ID = psp.FINPROD_ID inner join PTL_PORTFOLIO pp on pp.PORTFOLIO_ID = psp.PORTFOLIO_ID WHERE IFNULL(pp.PARENT_PORTFOLIO_ID,'null') = 'null' and psp.CDATE = STR_TO_DATE(#{regDate},'%Y-%m-%d') AND psp.HODING_TYPE = #{POSITION_TYPE03} AND fp.FINPROD_MARKET_ID = #{finprodMarketId}
